import os,json,subprocess
from pathlib import Path
paths={
"pink_vpn_state":"/var/lib/pink-vpn",
"pink_project":"/srv/projects/pink-iptv",
"pink_target":"/srv/projects/pink-iptv/vpn/data",
"rea_state":"/var/lib/rea-reversa",
"rea_oauth":"/var/lib/rea-mcp-oauth",
"rea_www":"/var/www/rea-reversa-acme",
"rea_private_root":"/var/lib/private/rea-mcp-oauth"}
out={"paths":{},"service_refs":{},"process_cwds":{},"service_active":{}}
for k,s in paths.items():
 p=Path(s)
 try:
  st=p.lstat()
  o={"exists":True,"kind":"link" if p.is_symlink() else "dir" if p.is_dir() else "file","uid":st.st_uid,"gid":st.st_gid,"mode":oct(st.st_mode&0o777),"dev":st.st_dev,"inode":st.st_ino}
  if p.is_symlink():o["target"]=os.readlink(s);o["resolved_exists"]=p.resolve(strict=False).exists()
  if p.is_dir() and not p.is_symlink():
   children=list(p.iterdir());o["children"]=len(children)
   o["child_kinds"]={"dirs":sum(x.is_dir() for x in children),"files":sum(x.is_file() for x in children),"links":sum(x.is_symlink() for x in children)}
  out["paths"][k]=o
 except FileNotFoundError:out["paths"][k]={"exists":False}
for k,s in paths.items():
 if k not in ("pink_vpn_state","rea_state","rea_oauth","rea_www"):continue
 matches=[]
 for base in ("/etc/systemd/system","/etc/nginx","/etc/cron.d","/usr/local/bin","/usr/local/sbin"):
  root=Path(base)
  if not root.is_dir():continue
  for f in root.iterdir():
   try:
    if f.is_file() and not f.is_symlink() and f.stat().st_size<80000 and s in f.read_text(errors="replace"):matches.append(str(f))
   except OSError:pass
 out["service_refs"][k]=matches[:25]
out["process_cwds"]={}
for proc in Path("/proc").iterdir():
 if not proc.name.isdecimal():continue
 try:
  cwd=os.readlink(str(proc/"cwd"))
  for k,s in paths.items():
   if k in ("pink_vpn_state","rea_state","rea_oauth","rea_www") and (cwd==s or cwd.startswith(s+"/")):
    out["process_cwds"].setdefault(k,[]).append((proc/"comm").read_text().strip())
 except OSError:pass
for name in ("pink-vpn","pink-iptv-backend","rea-reversa-mcp","rea-mcp-oauth","nginx","ssh"):
 out["service_active"][name]=subprocess.run(["systemctl","is-active",name],capture_output=True,text=True,timeout=7).stdout.strip()
print(json.dumps(out,sort_keys=True))
